#include "../include/sleela_vm_compiler_manager.h"
int sleela_vm_cm_manifest_validate(const sleela_vm_compile_manifest_t* m){if(!m||!m->profile_code||!m->required_object_count)return 0;if(m->minimum_object_count>m->maximum_object_count)return 0;if(m->declared_object_count<m->minimum_object_count||m->declared_object_count>m->maximum_object_count)return 0;return 1;}
int sleela_vm_cm_object_count_status(const sleela_vm_compile_manifest_t* m){if(!sleela_vm_cm_manifest_validate(m))return SLEELA_CM_INVALID;if(m->declared_object_count<m->required_object_count)return SLEELA_CM_MISSING;if(m->declared_object_count>m->required_object_count)return SLEELA_CM_EXCESS;return SLEELA_CM_FINE;}
int sleela_vm_cm_category_status(const sleela_vm_compile_manifest_t* m,uint32_t c,uint32_t actual){if(!m||!c)return SLEELA_CM_INVALID;uint32_t expected=0;switch(c){case 1:expected=m->architecture;break;case 2:expected=m->execution;break;case 3:expected=m->memory;break;case 4:expected=m->security;break;case 5:expected=m->io;break;case 6:expected=m->runtime;break;case 7:expected=m->management;break;case 8:expected=m->linkage;break;case 9:expected=m->observability;break;case 10:expected=m->build;break;default:return SLEELA_CM_INVALID;}return actual<expected?SLEELA_CM_MISSING:actual>expected?SLEELA_CM_EXCESS:SLEELA_CM_FINE;}
int sleela_vm_cm_dependency_required(uint32_t object_code,uint32_t requirement_code){return object_code!=0&&requirement_code!=0;}
const char* sleela_vm_cm_status_name(uint32_t s){switch(s){case 1:return "FINE";case 2:return "MISSING";case 3:return "EXCESS";case 4:return "REQUIRES";case 5:return "INVALID";default:return "UNKNOWN";}}
